from fractions import Fraction as fracimport remo = re.compile(r"^[+-]?[\d]*\.[\d]*\([\d()]+\)$") #match objectni = True   #Need Inputwhile ni:    # Line input    print('Use () to indicate repeting decmials ~leave blank to exit.')    l =  input('Enter repeating decimal: ')    hb = l.find('.(') > -1   # Have Base    pp = l.find('(')         # Parenthesis position    pd = l.find('.')         # decimal postition#    oi = int(l[:pd])        # original integer     pcp = l.find(')')        # parenthesis close position    rds = l[pp:(pcp+1)]      # repeating decimal string    #print('~new rds = {}'.format(rds))    if len(l) == 0:        break    if not bool(mo.match(l)):        print('Invaild repeating decimal format!\n{}'.format(l))        continue    print('\nLet x = {}'.format(l))    npl = l.replace('(','').replace(')','') # no parentheis l    fl = float(npl)     #float of l    # handle any non repeating decial digits    ltm = 0           #Lesser Tens Multipler    if not(hb):        ltm = pp - pd -1        lmv = 10**ltm  #Lesser Multiplier value        na = int(fl * lmv)  #Numerator Adjustment        #print('fl = {}  lmv = {}  na = {}'.format(fl,lmv,na))        print('{}x = {}.{}'.format(lmv,na,rds))    else:        lmv = 1        na = int(fl)     #print('na = {}'.format(na))     mtf = ltm + (pcp - pp - 1)  #Multiple of ten factor    mv = 10**mtf         # multiplier value    d = mv-lmv           # Denominator    mlf = int(fl * mv)   # multiplied float value    #print('mlf = {}  mv = {}'.format(mlf,mv))    print('{}x = {}.{}'.format(mv,mlf,rds))    n = int(mlf- na)    # Numerator    #print('Calculted values Numerator: {}  Denominator: {}'.format(n,d))    a = frac(n,d)       # Answer    print('{}x = {}\n'.format(d,n))    print('Fraction = {}'.format(a))    num = a.numerator    den = a.denominator    if num > den:        bi = num // den  # Base Integer        nn = num % den   # New Numerator        print('Mixed = {} {}/{}'.format(bi,nn,den))    